<?php require_once 'config.php'; if (current_user()) redirect(current_user()['role']==='admin'?'admin_dashboard.php':'menu.php'); if ($_SERVER['REQUEST_METHOD']==='POST') { $email=trim($_POST['email']??''); $pass=$_POST['password']??''; $s=db()->prepare("SELECT * FROM users WHERE email=? AND role='admin'"); $s->bind_param('s',$email); $s->execute(); $u=$s->get_result()->fetch_assoc(); if ($u && password_verify($pass,$u['password_hash'])) { $_SESSION['user']=['id'=>$u['id'],'name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role']]; redirect('admin_dashboard.php'); } flash('Invalid admin login.'); } ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="assets/style.css"></head><body><form class="auth-card solo" method="post"><h2>Admin Login</h2><?php if($m=flash()):?><div class="error"><?=h($m)?></div><?php endif;?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button>Login</button><p><a href="login.php">User login</a></p></form></body></html>
